(window.KOTOBA_HK=window.KOTOBA_HK||{})[15]={"n":15,"S":[{"id":"l15a","ti":[[["うぐいす","うぐいす"],["の","の"],["里","さと"],["と","と"]],[["三つ","みっつ"],["の","の"],["卵","たまご"]]],"tt":{"az":"Bülbüllər diyarı və üç yumurta","en":"The Warbler’s Village and the Three Eggs","ru":"Край камышовки и три яйца"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["ある","ある","ある(連体詞)"]],[["山","やま"],["の","の"]],[["近く","ちかく"],["に","に"],["、"],["おじいさん","おじいさん"],["が","が"]],[["住んでいました","すんでいました","住む",31],["。"],["おじいさん","おじいさん"],["は","は"]],[["竹","たけ"],["で","で","だ"]],[["かご","かご"],["を","を"]],[["作っていました","つくっていました","作る",15],["。"],["ある","ある","ある(連体詞)"]],[["春","はる"],["の","の"]],[["日","ひ"],["、"],["山","やま"],["の","の"]],[["奥","おく"],["で","で","だ"]],[["道","みち"],["が","が"]],[["わからなく","わからなく","わかる",19],["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Qədim zamanlarda bir dağın yaxınlığında bir qoca yaşayırdı. O, bambukdan səbətlər düzəldirdi. Bir yaz günü dağın dərinliklərində yolu itirdi.","en":"Long ago, an old man lived near a mountain. He made baskets from bamboo. One spring day, he lost his way deep in the mountain.","ru":"Давным-давно возле горы жил старик. Он делал корзины из бамбука. Однажды весной он заблудился в глубине гор."}},{"t":[[["木","き"],["の","の"]],[["向こう","むこう"],["に","に"],["、"],["りっぱな","りっぱな","りっぱ",1]],[["家","いえ"],["が","が"]],[["ありました","ありました","ある",2],["。"],["若い","わかい"]],[["女","おんな"],["の","の"]],[["人","ひと"],["が","が"]],[["門","もん"],["の","の"]],[["前","まえ"],["に","に"]],[["立っていました","たっていました","立つ",15],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["すみません","すみません","すむ",6],["。"],["ここ","ここ"],["で","で"]],[["休んでも","やすんでも","休む",32]],[["いい","いい"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"]]],"tr":{"az":"Ağacların o tərəfində gözəl bir ev vardı. Darvazanın qarşısında gənc bir qadın dayanmışdı. Qoca soruşdu: «Bağışlayın. Burada dincələ bilərəm?»","en":"Beyond the trees stood a fine house. A young woman was standing at the gate. The old man asked, “Excuse me. May I rest here?”","ru":"За деревьями стоял красивый дом. Перед воротами стояла молодая женщина. Старик спросил: «Извините. Можно здесь отдохнуть?»"}},{"t":[[["女","おんな"],["の","の"]],[["人","ひと"],["は","は"]],[["おじいさん","おじいさん"],["を","を"]],[["家","いえ"],["に","に"]],[["入れました","いれました","入れる",2],["。"],["「"],["私","わたし"],["は","は"]],[["ここ","ここ"],["に","に"]],[["住んでいます","すんでいます","住む",33],["。"],["この","この"]],[["山","やま"],["の","の"]],[["道","みち"],["を","を"]],[["よく","よく"]],[["知っています","しっています","知る",24],["」"],["。"],["そして","そして"],["、"],["机","つくえ"],["に","に"]],[["温かい","あたたかい"]],[["お茶","おちゃ"],["と","と"]],[["甘い","あまい"]],[["お菓子","おかし"],["を","を"]],[["置きました","おきました","置く",2],["。"]]],"tr":{"az":"Qadın qocanı evə buraxdı. «Mən burada yaşayıram. Bu dağın yollarını yaxşı tanıyıram», – dedi. Sonra masaya isti çay və şirniyyat qoydu.","en":"The woman welcomed the old man inside. “I live here. I know the mountain paths well.” Then she placed warm tea and sweets on the table.","ru":"Женщина впустила старика в дом. «Я живу здесь. Я хорошо знаю горные тропинки». Затем она поставила на стол тёплый чай и сладости."}},{"t":[[["やがて","やがて"]],[["女","おんな"],["の","の"]],[["人","ひと"],["は","は"],["「"],["少し","すこし"]],[["出かけます","でかけます","出かける",11],["。"],["でも","でも"],["、"],["奥","おく"],["の","の"]],[["部屋","へや"],["に","に"]],[["入って","はいって","入る",3],["は","は"]],[["いけません","いけません","いける",6],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["庭","にわ"],["を","を"]],[["見ても","みても","見る",34]],[["いい","いい"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["「"],["ええ","ええ"],["、"],["庭","にわ"],["は","は"]],[["いい","いい"],["です","です"],["よ","よ"],["」"],["。"]]],"tr":{"az":"Bir az sonra qadın dedi: «Bir azlıq çıxıram. Amma arxadakı otağa girmək olmaz». Qoca soruşdu: «Bağçaya baxa bilərəm?» «Bəli, bağçaya baxa bilərsiniz».","en":"Soon the woman said, “I’m going out for a little while. But you must not enter the back room.” The old man asked, “May I look at the garden?” “Yes, the garden is fine.”","ru":"Вскоре женщина сказала: «Я ненадолго уйду. Но в дальнюю комнату входить нельзя». Старик спросил: «Можно посмотреть сад?» «Да, сад посмотреть можно»."}},{"t":[[["庭","にわ"],["の","の"]],[["花","はな"],["は","は"]],[["きれい","きれい"],["でした","でした","です",9],["。"],["でも","でも"],["、"],["奥","おく"],["の","の"]],[["部屋","へや"],["から","から"]],[["小さい","ちいさい"]],[["音","おと"],["が","が"]],[["しました","しました","する",2],["。"],["おじいさん","おじいさん"],["は","は"]],[["戸","と"],["を","を"]],[["少し","すこし"]],[["開けました","あけました","開ける",2],["。"],["部屋","へや"],["に","に"],["は","は"]],[["三人","さんにん"],["の","の"]],[["女","おんな"],["の","の"]],[["子","こ"],["が","が"]],[["いて","いて","いる",3],["、"],["きれいな","きれいな","きれい",1]],[["服","ふく"],["を","を"]],[["着ていました","きていました","着る",15],["。"]]],"tr":{"az":"Bağçadakı çiçəklər gözəl idi. Amma arxadakı otaqdan zəif bir səs gəldi. Qoca qapını azca açdı. Otaqda gözəl paltarlar geyinmiş üç qız vardı.","en":"The flowers in the garden were lovely. But a faint sound came from the back room. The old man opened the door a little. Inside were three girls wearing beautiful clothes.","ru":"Цветы в саду были прекрасны. Но из дальней комнаты послышался тихий звук. Старик приоткрыл дверь. В комнате были три девочки в красивых нарядах."}},{"t":[[["女","おんな"],["の","の"]],[["子たち","こたち"],["は","は"]],[["おじいさん","おじいさん"],["を","を"]],[["見て","みて","見る",3],["、"],["鳥","とり"],["に","に"]],[["なって","なって","なる",3]],[["飛びました","とびました","飛ぶ",2],["。"],["部屋","へや"],["の","の"]],[["棚","たな"],["に","に"],["は","は"],["、"],["三つ","みっつ"],["の","の"]],[["卵","たまご"],["が","が"]],[["ありました","ありました","ある",2],["。"],["「"],["これ","これ"],["は","は"]],[["何","なん"],["の","の"]],[["卵","たまご"],["です","です"],["か","か"],["」"],["。"],["おじいさん","おじいさん"],["は","は"]],[["一つ","ひとつ"]],[["手","て"],["に","に"]],[["取りました","とりました","取る",2],["。"]]],"tr":{"az":"Qızlar qocanı görüb quşa çevrildilər və uçub getdilər. Otaqdakı rəfdə üç yumurta vardı. «Bunlar hansı quşun yumurtalarıdır?» Qoca birini əlinə aldı.","en":"When the girls saw the old man, they turned into birds and flew away. There were three eggs on a shelf in the room. “What kind of eggs are these?” The old man picked one up.","ru":"Увидев старика, девочки превратились в птиц и улетели. На полке в комнате лежали три яйца. «Чьи это яйца?» Старик взял одно в руку."}},{"t":[[["その","その"],["とき","とき"],["、"],["卵","たまご"],["が","が"]],[["手","て"],["から","から"]],[["落ちました","おちました","落ちる",2],["。"],["ほか","ほか"],["の","の"]],[["二つ","ふたつ"],["も","も"]],[["棚","たな"],["から","から"]],[["落ちて","おちて","落ちる",3],["、"],["全部","ぜんぶ"]],[["割れました","われました","割れる",2],["。"],["女","おんな"],["の","の"]],[["人","ひと"],["が","が"]],[["帰ってきました","かえってきました","帰る",23],["。"],["「"],["ここ","ここ"],["に","に"],["は","は"]],[["私","わたし"],["の","の"]],[["家族","かぞく"],["が","が"]],[["住んでいます","すんでいます","住む",33],["。"],["卵","たまご"],["に","に"]],[["触って","さわって","触る",3],["は","は"]],[["いけません","いけません","いける",6],["！"],["」"]]],"tr":{"az":"Elə bu vaxt yumurta əlindən düşdü. O biri iki yumurta da rəfdən düşdü və hamısı sındı. Qadın geri qayıtdı. «Burada mənim ailəm yaşayır. Yumurtalara toxunmaq olmaz!»","en":"Just then, the egg slipped from his hand. The other two fell from the shelf as well, and all three broke. The woman returned. “My family lives here. You must not touch the eggs!”","ru":"В этот миг яйцо выпало у него из руки. Два других тоже упали с полки, и все три разбились. Женщина вернулась. «Здесь живёт моя семья. Яйца трогать нельзя!»"}},{"t":[[["女","おんな"],["の","の"]],[["人","ひと"],["は","は"]],[["悲しい","かなしい"]],[["声","こえ"],["で","で","だ"]],[["鳴いて","ないて","鳴く",3],["、"],["うぐいす","うぐいす"],["に","に"]],[["なりました","なりました","なる",2],["。"],["家","いえ"],["も","も"]],[["庭","にわ"],["も","も"]],[["消えました","きえました","消える",2],["。"],["おじいさん","おじいさん"],["は","は"]],[["毎年","まいとし"]],[["春","はる"],["に","に"],["、"],["その","その"]],[["声","こえ"],["を","を"]],[["思い出しました","おもいだしました","思い出す",2],["。"],["そして","そして"],["、"],["山","やま"],["に","に"]],[["向かって","むかって","向かう",3]],[["静かに","しずかに","静か",8]],[["謝りました","あやまりました","謝る",2],["。"]]],"tr":{"az":"Qadın kədərli bir səslə ötüb bülbülə çevrildi. Ev də, bağça da yox oldu. Qoca hər yaz onun səsini xatırlayırdı. Üzünü dağa tutub sakitcə üzr istəyirdi.","en":"The woman gave a sorrowful cry and turned into a Japanese bush warbler. The house and garden vanished. Every spring, the old man remembered her voice. He faced the mountain and quietly apologized.","ru":"Женщина печально вскрикнула и превратилась в японскую камышовку. Дом и сад исчезли. Каждую весну старик вспоминал её голос. Он поворачивался к горе и тихо просил прощения."}}]},{"id":"l15b","ti":[[["さくら","さくら"],["寮","りょう"],["の","の"]],[["白い","しろい"]],[["友達","ともだち"]]],"tt":{"az":"Sakura yataqxanasının ağ dostu","en":"The White Friend of Sakura Dormitory","ru":"Белый друг общежития «Сакура»"},"P":[{"t":[[["春","はる"],["に","に"],["、"],["レン","レン"],["は","は"]],[["さくら","さくら"],["寮","りょう"],["に","に"]],[["来ました","きました","来る",2],["。"],["この","この"]],[["寮","りょう"],["に","に"],["は","は"]],[["十人","じゅうにん"],["の","の"]],[["学生","がくせい"],["が","が"]],[["住んでいました","すんでいました","住む",31],["。"],["玄関","げんかん"],["に","に"],["は","は"],["「"],["夜","よる"]],[["十","じゅう"],["時","じ"],["に","に"],["、"],["台所","だいどころ"],["の","の"]],[["机","つくえ"],["に","に"]],[["お茶","おちゃ"],["を","を"]],[["置いてください","おいてください","置く",35],["」"],["と","と"]],[["書いてありました","かいてありました","書く",36],["。"]]],"tr":{"az":"Yazda Ren Sakura yataqxanasına gəldi. Bu yataqxanada on tələbə yaşayırdı. Girişdə belə yazılmışdı: «Axşam saat onda mətbəxdəki masaya çay qoyun».","en":"In spring, Ren arrived at Sakura Dormitory. Ten students lived there. At the entrance was a notice: “Please put tea on the kitchen table at ten at night.”","ru":"Весной Рэн приехал в общежитие «Сакура». Здесь жили десять студентов. У входа было написано: «В десять часов вечера поставьте чай на кухонный стол»."}},{"t":[[["寮","りょう"],["の","の"]],[["おばさん","おばさん"],["は","は"]],[["三つ","みっつ"],["の","の"]],[["約束","やくそく"],["を","を"]],[["教えました","おしえました","教える",2],["。"],["「"],["夜","よる"],["は","は"]],[["窓","まど"],["を","を"]],[["閉めて","しめて","閉める",3],["は","は"]],[["いけません","いけません","いける",6],["。"],["白い","しろい"]],[["帽子","ぼうし"],["に","に"]],[["触って","さわって","触る",3],["は","は"]],[["いけません","いけません","いける",6],["。"],["それから","それから"],["、"],["お茶","おちゃ"],["を","を"]],[["飲んでも","のんでも","飲む",32]],[["いい","いい"],["です","です"],["が","が"],["、"],["一つ","ひとつ"]],[["残してください","のこしてください","残す",35],["」"],["。"]]],"tr":{"az":"Yataqxanaya baxan qadın ona üç qaydanı izah etdi. «Gecə pəncərəni bağlamaq olmaz. Ağ papağa toxunmaq olmaz. Bir də çay içə bilərsiniz, amma bir fincan saxlayın».","en":"The woman who looked after the dormitory explained three rules. “You must not close the window at night. You must not touch the white hat. And you may drink the tea, but leave one cup.”","ru":"Смотрительница объяснила три правила. «Ночью нельзя закрывать окно. Нельзя трогать белую шапку. И ещё: чай пить можно, но одну чашку оставляйте»."}},{"t":[[["その","その"]],[["夜","よる"],["、"],["レン","レン"],["は","は"]],[["机","つくえ"],["に","に"]],[["お茶","おちゃ"],["を","を"]],[["置きました","おきました","置く",2],["。"],["する","する","する",5],["と","と"],["、"],["白い","しろい"]],[["小さな","ちいさな"]],[["おばけ","おばけ"],["が","が"]],[["窓","まど"],["から","から"]],[["入ってきました","はいってきました","入る",23],["。"],["「"],["隣","となり"],["に","に"]],[["座っても","すわっても","座る",34]],[["いい","いい"],["です","です"],["か","か"],["」"],["。"],["おばけ","おばけ"],["は","は"]],[["丁寧に","ていねいに","丁寧",8]],[["聞きました","ききました","聞く",2],["。"]]],"tr":{"az":"Həmin gecə Ren masaya çay qoydu. Bu zaman pəncərədən balaca ağ bir kabus içəri girdi. «Yanında otura bilərəm?» – deyə kabus nəzakətlə soruşdu.","en":"That night, Ren put tea on the table. A small white ghost came in through the window. “May I sit beside you?” the ghost asked politely.","ru":"В тот вечер Рэн поставил чай на стол. Тут через окно влетело маленькое белое привидение. «Можно сесть рядом?» – вежливо спросило оно."}},{"t":[[["おばけ","おばけ"],["の","の"]],[["名前","なまえ"],["は","は"]],[["シロ","シロ"],["でした","でした","です",9],["。"],["「"],["ぼく","ぼく"],["は","は"]],[["この","この"]],[["寮","りょう"],["に","に"]],[["住んでいます","すんでいます","住む",33],["。"],["皆さん","みなさん"],["の","の"]],[["名前","なまえ"],["も","も"]],[["知っています","しっています","知る",24],["」"],["。"],["シロ","シロ"],["は","は"]],[["毎晩","まいばん"],["、"],["学生","がくせい"],["の","の"]],[["服","ふく"],["に","に"]],[["ボタン","ボタン"],["を","を"]],[["つけていました","つけていました","つける",15],["。"],["白い","しろい"]],[["帽子","ぼうし"],["は","は"]],[["母","はは"],["の","の"]],[["プレゼント","プレゼント"],["でした","でした","です",9],["。"]]],"tr":{"az":"Kabusun adı Şiro idi. «Mən bu yataqxanada yaşayıram. Hamının adını da bilirəm». Şiro hər gecə tələbələrin paltarlarına düymə tikirdi. Ağ papağı anasının hədiyyəsi idi.","en":"The ghost’s name was Shiro. “I live in this dormitory. I know everyone’s name, too.” Every night, Shiro sewed buttons onto the students’ clothes. His white hat was a gift from his mother.","ru":"Привидение звали Сиро. «Я живу в этом общежитии. И знаю имена всех жильцов». Каждую ночь Сиро пришивал пуговицы к одежде студентов. Белая шапка была подарком мамы."}},{"t":[[["次","つぎ"],["の","の"]],[["晩","ばん"],["は","は"],["、"],["とても","とても"]],[["寒かった","さむかった","寒い",0],["です","です"],["。"],["レン","レン"],["は","は"]],[["約束","やくそく"],["を","を"]],[["忘れて","わすれて","忘れる",3],["、"],["窓","まど"],["を","を"]],[["閉めました","しめました","閉める",2],["。"],["十","じゅう"],["時","じ"],["に","に"]],[["お茶","おちゃ"],["を","を"]],[["置きました","おきました","置く",2],["が","が"],["、"],["シロ","シロ"],["は","は"]],[["来ませんでした","きませんでした","来る",4],["。"],["廊下","ろうか"],["に","に"],["は","は"]],[["ボタン","ボタン"],["が","が"]],[["一つ","ひとつ"]],[["落ちていました","おちていました","落ちる",15],["。"]]],"tr":{"az":"Növbəti axşam hava çox soyuq idi. Ren qaydanı unudub pəncərəni bağladı. Saat onda çayı qoydu, amma Şiro gəlmədi. Dəhlizdə yerə düşmüş bir düymə vardı.","en":"The next evening was very cold. Ren forgot the rule and closed the window. He put out the tea at ten, but Shiro did not come. A button lay on the hallway floor.","ru":"На следующий вечер было очень холодно. Рэн забыл правило и закрыл окно. В десять он поставил чай, но Сиро не пришёл. На полу в коридоре лежала пуговица."}},{"t":[[["レン","レン"],["は","は"]],[["シロ","シロ"],["を","を"]],[["捜しました","さがしました","捜す",2],["。"],["小さな","ちいさな"]],[["声","こえ"],["が","が"]],[["窓","まど"],["の","の"]],[["外","そと"],["から","から"]],[["聞こえました","きこえました","聞こえる",2],["。"],["「"],["すみません","すみません","すむ",6],["。"],["開けても","あけても","開ける",34]],[["いい","いい"],["です","です"],["か","か"],["」"],["。"],["シロ","シロ"],["は","は"]],[["外","そと"],["に","に"]],[["いました","いました","いる",2],["。"],["帽子","ぼうし"],["が","が"]],[["窓","まど"],["に","に"]],[["挟まっていました","はさまっていました","挟まる",15],["。"]]],"tr":{"az":"Ren Şironu axtardı. Pəncərənin o tərəfindən zəif bir səs eşidildi. «Bağışla. Aça bilərəm?» Şiro bayırda idi. Papağı pəncərənin arasında qalmışdı.","en":"Ren searched for Shiro. A small voice came from outside the window. “Excuse me. May I open it?” Shiro was outside. His hat was caught in the window.","ru":"Рэн стал искать Сиро. Из-за окна послышался тихий голос. «Извини. Можно открыть?» Сиро был снаружи. Его шапку зажало окном."}},{"t":[[["レン","レン"],["は","は"]],[["急いで","いそいで","急ぐ",13]],[["窓","まど"],["を","を"]],[["開けました","あけました","開ける",2],["。"],["「"],["ごめん","ごめん"],["なさい","なさい","なさる",10],["。"],["帽子","ぼうし"],["に","に"]],[["触っても","さわっても","触る",34]],[["いい","いい"],["です","です"],["か","か"],["」"],["。"],["シロ","シロ"],["は","は"],["「"],["今","いま"],["は","は"]],[["いい","いい"],["です","です"],["よ","よ"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"],["レン","レン"],["は","は"]],[["帽子","ぼうし"],["を","を"]],[["取って","とって","取る",3],["、"],["シロ","シロ"],["に","に"]],[["渡しました","わたしました","渡す",2],["。"]]],"tr":{"az":"Ren tələsik pəncərəni açdı. «Bağışla. Papağa toxuna bilərəm?» Şiro cavab verdi: «İndi olar». Ren papağı çıxarıb Şiroya verdi.","en":"Ren hurried to open the window. “I’m sorry. May I touch your hat?” “You may now,” Shiro replied. Ren freed the hat and handed it to him.","ru":"Рэн поспешно открыл окно. «Прости. Можно потрогать шапку?» Сиро ответил: «Теперь можно». Рэн вытащил шапку и отдал её Сиро."}},{"t":[[["「"],["壁","かべ"],["は","は"]],[["通れます","とおれます","通れる",11],["。"],["でも","でも"],["、"],["この","この"]],[["帽子","ぼうし"],["は","は"]],[["通れません","とおれません","通れる",6],["」"],["。"],["シロ","シロ"],["は","は"]],[["笑いました","わらいました","笑う",2],["。"],["次","つぎ"],["の","の"]],[["日","ひ"],["、"],["レン","レン"],["は","は"]],[["帽子","ぼうし"],["に","に"]],[["小さな","ちいさな"]],[["ボタン","ボタン"],["を","を"]],[["つけました","つけました","つける",2],["。"],["シロ","シロ"],["は","は"]],[["今","いま"],["も","も"],["、"],["その","その"]],[["大切な","たいせつな","大切",1]],[["帽子","ぼうし"],["を","を"]],[["かぶっています","かぶっています","かぶる",24],["。"]]],"tr":{"az":"«Divardan keçə bilirəm. Amma bu papaq keçə bilmir». Şiro güldü. Ertəsi gün Ren papağa balaca bir düymə tikdi. Şiro indi də o əziz papağını taxır.","en":"“I can go through walls. But this hat can’t.” Shiro laughed. The next day, Ren sewed a little button onto the hat. Shiro still wears his precious hat today.","ru":"«Я могу проходить сквозь стены. А эта шапка не может». Сиро рассмеялся. На следующий день Рэн пришил к шапке маленькую пуговицу. Сиро до сих пор носит свою любимую шапку."}}]},{"id":"l15c","ti":[[["祖父","そふ"],["の","の"]],[["ひみつ","ひみつ"],["の","の"]],[["仕事","しごと"]]],"tt":{"az":"Babanın gizli işi","en":"Grandpa’s Secret Job","ru":"Тайная работа дедушки"},"P":[{"t":[[["ミナ","ミナ"],["は","は"]],[["父","ちち"],["と","と"]],[["母","はは"],["と","と"]],[["祖父","そふ"],["と","と"]],[["住んでいました","すんでいました","住む",31],["。"],["父","ちち"],["は","は"]],[["市","し"],["役所","やくしょ"],["で","で","だ"]],[["働いていました","はたらいていました","働く",15],["。"],["母","はは"],["は","は"]],[["歯","は"],["医者","いしゃ"],["でした","でした","です",9],["。"],["でも","でも"],["、"],["祖父","そふ"],["の","の"]],[["仕事","しごと"],["は","は"]],[["よく","よく"]],[["わかりませんでした","わかりませんでした","わかる",4],["。"]]],"tr":{"az":"Mina atası, anası və babası ilə yaşayırdı. Atası şəhər idarəsində işləyirdi. Anası diş həkimi idi. Amma babasının nə iş gördüyünü yaxşı bilmirdi.","en":"Mina lived with her father, mother, and grandfather. Her father worked at city hall. Her mother was a dentist. But she was not quite sure what her grandfather did.","ru":"Мина жила с папой, мамой и дедушкой. Папа работал в мэрии. Мама была стоматологом. Но чем занимался дедушка, Мина толком не знала."}},{"t":[[["祖父","そふ"],["は","は"]],[["毎朝","まいあさ"],["、"],["小さな","ちいさな"]],[["部屋","へや"],["に","に"]],[["入りました","はいりました","入る",2],["。"],["机","つくえ"],["に","に"],["は","は"]],[["服","ふく"],["の","の"]],[["カタログ","カタログ"],["と","と"]],[["古い","ふるい"]],[["写真","しゃしん"],["が","が"]],[["ありました","ありました","ある",2],["。"],["棚","たな"],["に","に"],["は","は"]],[["小さな","ちいさな"]],[["箱","はこ"],["を","を"]],[["たくさん","たくさん"]],[["置いていました","おいていました","置く",15],["。"],["ミナ","ミナ"],["は","は"]],[["その","その"]],[["部屋","へや"],["に","に"]],[["入った","はいった","入る",0]],[["こと","こと"],["が","が"]],[["ありませんでした","ありませんでした","ある",4],["。"]]],"tr":{"az":"Babası hər səhər balaca bir otağa girirdi. Masanın üstündə geyim kataloqları və köhnə şəkillər vardı. Rəfdə çoxlu balaca qutu saxlayırdı. Mina o otağa heç girməmişdi.","en":"Every morning, Grandpa went into a small room. Clothing catalogs and old photographs lay on his desk. He kept many little boxes on a shelf. Mina had never been inside that room.","ru":"Каждое утро дедушка заходил в маленькую комнату. На столе лежали каталоги одежды и старые фотографии. На полке он хранил много маленьких коробок. Мина ещё ни разу не бывала в этой комнате."}},{"t":[[["ある","ある","ある(連体詞)"]],[["日","ひ"],["、"],["学校","がっこう"],["で","で","だ"]],[["家族","かぞく"],["の","の"]],[["仕事","しごと"],["を","を"]],[["話しました","はなしました","話す",2],["。"],["ミナ","ミナ"],["は","は"]],[["祖父","そふ"],["の","の"]],[["仕事","しごと"],["だけ","だけ"]],[["話せませんでした","はなせませんでした","話せる",4],["。"],["家","いえ"],["に","に"]],[["帰って","かえって","帰る",3],["、"],["「"],["おじいちゃん","おじいちゃん"],["、"],["仕事","しごと"],["を","を"]],[["見ても","みても","見る",34]],[["いい","いい"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"]]],"tr":{"az":"Bir gün məktəbdə ailə üzvlərinin işləri haqqında danışdılar. Mina yalnız babasının işindən danışa bilmədi. Evə qayıdıb soruşdu: «Baba, işinə baxa bilərəm?»","en":"One day, the children talked about their families’ jobs at school. Mina could not explain only her grandfather’s work. When she got home, she asked, “Grandpa, may I watch you work?”","ru":"Однажды в школе дети рассказывали о работе своих родных. Мина не смогла рассказать только о работе дедушки. Вернувшись домой, она спросила: «Дедушка, можно посмотреть, как ты работаешь?»"}},{"t":[[["祖父","そふ"],["は","は"]],[["笑って","わらって","笑う",3],["、"],["戸","と"],["を","を"]],[["開けました","あけました","開ける",2],["。"],["「"],["入っても","はいっても","入る",34]],[["いい","いい"],["よ","よ"],["。"],["でも","でも"],["、"],["この","この"]],[["箱","はこ"],["を","を"]],[["開けて","あけて","開ける",3],["は","は"]],[["いけません","いけません","いける",6],["」"],["。"],["ミナ","ミナ"],["は","は"]],[["机","つくえ"],["の","の"]],[["上","うえ"],["を","を"]],[["見ました","みました","見る",2],["。"],["そこ","そこ"],["に","に"],["は","は"]],[["赤い","あかい"]],[["服","ふく"],["と","と"]],[["とても","とても"]],[["小さい","ちいさい"]],[["靴","くつ"],["が","が"]],[["ありました","ありました","ある",2],["。"]]],"tr":{"az":"Babası gülümsəyib qapını açdı. «Girə bilərsən. Amma bu qutunu açmaq olmaz». Mina masanın üstünə baxdı. Orada qırmızı bir paltar və çox balaca ayaqqabılar vardı.","en":"Grandpa smiled and opened the door. “You may come in. But you must not open this box.” Mina looked at the desk. There was a red outfit and a very tiny pair of shoes.","ru":"Дедушка улыбнулся и открыл дверь. «Заходи. Но эту коробку открывать нельзя». Мина посмотрела на стол. Там лежали красный наряд и совсем крошечные туфли."}},{"t":[[["「"],["赤ちゃん","あかちゃん"],["の","の"]],[["服","ふく"],["を","を"]],[["作っています","つくっています","作る",24],["か","か"],["」"],["。"],["祖父","そふ"],["は","は"]],[["首","くび"],["を","を"]],[["横","よこ"],["に","に"]],[["振りました","ふりました","振る",2],["。"],["「"],["人形","にんぎょう"],["の","の"]],[["服","ふく"],["を","を"]],[["作っています","つくっています","作る",24],["。"],["駅","えき"],["の","の"]],[["前","まえ"],["の","の"]],[["店","みせ"],["で","で","だ"]],[["売っています","うっています","売る",24],["」"],["。"],["ミナ","ミナ"],["は","は"]],[["初めて","はじめて"]],[["祖父","そふ"],["の","の"]],[["仕事","しごと"],["を","を"]],[["知りました","しりました","知る",2],["。"]]],"tr":{"az":"«Körpə paltarları tikirsən?» Babası başını buladı. «Kukla paltarları tikirəm. Vağzalın qarşısındakı mağazada satıram». Mina babasının işini ilk dəfə öyrəndi.","en":"“Do you make baby clothes?” Grandpa shook his head. “I make clothes for dolls. I sell them at the shop in front of the station.” For the first time, Mina learned what her grandfather did.","ru":"«Ты шьёшь одежду для малышей?» Дедушка покачал головой. «Я шью одежду для кукол. Продаю её в магазине перед вокзалом». Мина впервые узнала, чем занимается дедушка."}},{"t":[[["ミナ","ミナ"],["は","は"],["「"],["私","わたし"],["も","も"]],[["作っても","つくっても","作る",34]],[["いい","いい"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["祖父","そふ"],["は","は"]],[["小さな","ちいさな"]],[["布","ぬの"],["を","を"]],[["渡しました","わたしました","渡す",2],["。"],["「"],["針","はり"],["を","を"]],[["床","ゆか"],["に","に"]],[["置いて","おいて","置く",3],["は","は"]],[["いけません","いけません","いける",6],["。"],["この","この"]],[["箱","はこ"],["に","に"]],[["入れてください","いれてください","入れる",35],["」"],["。"],["二人","ふたり"],["は","は"]],[["赤い","あかい"]],[["服","ふく"],["に","に"]],[["白い","しろい"]],[["花","はな"],["を","を"]],[["つけました","つけました","つける",2],["。"]]],"tr":{"az":"Mina soruşdu: «Mən də tikə bilərəm?» Babası ona balaca bir parça verdi. «İynəni yerə qoymaq olmaz. Bu qutuya qoy». İkisi birlikdə qırmızı paltara ağ bir çiçək tikdi.","en":"Mina asked, “May I make something, too?” Grandpa gave her a small piece of cloth. “You must not put the needle on the floor. Please put it in this box.” Together, they attached a white flower to the red outfit.","ru":"Мина спросила: «Можно мне тоже что-нибудь сшить?» Дедушка дал ей маленький кусочек ткани. «Иголку нельзя класть на пол. Клади её в эту коробочку». Вместе они пришили белый цветок к красному наряду."}},{"t":[[["次","つぎ"],["の","の"]],[["日","ひ"],["は","は"]],[["ミナ","ミナ"],["の","の"]],[["誕生","たんじょう"],["日","ひ"],["でした","でした","です",9],["。"],["祖父","そふ"],["は","は"]],[["あの","あの"]],[["箱","はこ"],["を","を"]],[["ミナ","ミナ"],["に","に"]],[["渡しました","わたしました","渡す",2],["。"],["中","なか"],["に","に"],["は","は"]],[["古い","ふるい"]],[["人形","にんぎょう"],["が","が"]],[["入っていました","はいっていました","入る",15],["。"],["人形","にんぎょう"],["は","は"]],[["昨日","きのう"],["の","の"]],[["赤い","あかい"]],[["服","ふく"],["を","を"]],[["着て","きて","着る",3],["、"],["あの","あの"]],[["小さい","ちいさい"]],[["靴","くつ"],["を","を"]],[["履いていました","はいていました","履く",15],["。"]]],"tr":{"az":"Ertəsi gün Minanın ad günü idi. Babası həmin qutunu ona verdi. İçində köhnə bir kukla vardı. Kukla dünənki qırmızı paltarı və o balaca ayaqqabıları geyinmişdi.","en":"The next day was Mina’s birthday. Grandpa gave her the box. Inside was an old doll. It was wearing yesterday’s red outfit and the tiny shoes.","ru":"На следующий день у Мины был день рождения. Дедушка подарил ей ту самую коробку. Внутри лежала старая кукла. На ней были вчерашний красный наряд и те самые крошечные туфли."}},{"t":[[["母","はは"],["は","は"],["「"],["この","この"]],[["人形","にんぎょう"],["、"],["知っています","しっています","知る",24],["。"],["私","わたし"],["の","の"]],[["人形","にんぎょう"],["です","です"],["！"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["祖父","そふ"],["は","は"],["「"],["今","いま"],["は","は"]],[["ミナ","ミナ"],["の","の"]],[["人形","にんぎょう"],["です","です"],["よ","よ"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"],["ミナ","ミナ"],["は","は"]],[["人形","にんぎょう"],["を","を"]],[["抱いて","いだいて","抱く",3],["、"],["「"],["お母さん","おかあさん"],["も","も"]],[["一緒","いっしょ"],["に","に"]],[["遊んでも","あそんでも","遊ぶ",32]],[["いい","いい"],["です","です"],["よ","よ"],["」"],["と","と"]],[["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Anası dedi: «Bu kuklanı tanıyıram. Mənim kuklamdır!» Babası cavab verdi: «İndi Minanın kuklasıdır». Mina kuklanı qucaqlayıb gülə-gülə dedi: «Ana, sən də bizimlə oynaya bilərsən!»","en":"Her mother said, “I know this doll. It’s mine!” Grandpa replied, “Now it’s Mina’s doll.” Mina hugged the doll and laughed. “You may play with us too, Mom!”","ru":"Мама сказала: «Я знаю эту куклу. Это моя кукла!» Дедушка ответил: «Теперь она Минина». Мина обняла куклу и со смехом сказала: «Мама, тебе тоже можно с нами играть!»"}}]}],"G":{"あの":{"b":"あの","p":"dm","m":{"az":"o (uzaqdakı)","en":"that (over there)","ru":"тот (вдали)"},"n":{"az":"İsimdən əvvəl gəlir: あの人 = o adam, あの星 = o ulduz. Danışandan da, dinləyəndən də uzaq olan şey.","en":"Comes before a noun: あの人 = that person, あの星 = that star. Something far from both speakers.","ru":"Ставится перед существительным: あの人 = тот человек. Далеко от обоих собеседников."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いける":{"b":"行ける (いける)","p":"v","m":{"az":"gedə bilmək","en":"to be able to go","ru":"мочь пойти"},"n":{"az":"いけません qadağa ifadəsində olmaz deməkdir və bu halda 行ける potensial felindən fərqlidir.","en":"いけません can mean must not in prohibitions and is then distinct from the potential verb 行ける.","ru":"いけません в запретах означает нельзя и отличается от потенциального глагола 行ける."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"うぐいす":{"b":"鶯 (うぐいす)","p":"n","m":{"az":"yapon bülbülü; kolluq quşu","en":"Japanese bush warbler","ru":"японская камышовка"}},"ええ":{"b":"ええ","p":"in","m":{"az":"bəli; hə","en":"yes","ru":"да"},"n":{"az":"Danışıqda işlənən təsdiqdir, はい-dan daha az rəsmidir.","en":"A conversational yes, less formal than はい.","ru":"Разговорное «да», менее официальное, чем はい."}},"おじいさん":{"b":"おじいさん","p":"n","m":{"az":"baba; qoca kişi","en":"grandfather; old man","ru":"дедушка; старик"}},"おじいちゃん":{"b":"おじいちゃん","p":"n","m":{"az":"baba, babacan","en":"grandpa, grandfather","ru":"дедушка, дедуля"},"n":{"az":"おじいさん sözünün səmimi formasıdır; öz babasına və ya yaşlı kişiyə deyilə bilər.","en":"An affectionate form of おじいさん, used for one's grandfather or an elderly man.","ru":"Ласковая форма おじいさん, употребляемая для дедушки или пожилого мужчины."}},"おばけ":{"b":"おばけ","p":"n","m":{"az":"kabus, xəyalət","en":"ghost, apparition","ru":"привидение, призрак"}},"おばさん":{"b":"おばさん","p":"n","m":{"az":"xala; bibi; orta yaşlı qadın","en":"aunt; middle-aged woman","ru":"тётя; женщина средних лет"},"n":{"az":"おばあさん nənə və ya yaşlı qadın deməkdir, qarışdırmayın.","en":"Do not confuse it with おばあさん, meaning grandmother or elderly woman.","ru":"Не путайте с おばあさん, означающим бабушку или пожилую женщину."}},"お母さん":{"b":"お母さん (おかあさん)","p":"n","m":{"az":"ana","en":"mother; mom","ru":"мама; мать"},"n":{"az":"Anaya müraciətdə və başqasının anası haqqında işlənir; kənar şəxslərə öz anandan danışarkən adətən 母 deyilir.","en":"Used to address your mother or refer to someone else's; use 母 for your own mother when speaking to outsiders.","ru":"Используется при обращении к маме или о чужой матери; о своей матери посторонним обычно говорят 母."}},"お茶":{"b":"お茶 (おちゃ)","p":"n","m":{"az":"çay","en":"tea","ru":"чай"}},"お菓子":{"b":"お菓子 (おかし)","p":"n","m":{"az":"şirniyyat; qəlyanaltı","en":"sweets; snacks","ru":"сладости; снеки"}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かご":{"b":"籠 (かご)","p":"n","m":{"az":"səbət","en":"basket","ru":"корзина"}},"かぶる":{"b":"被る (かぶる)","p":"v","m":{"az":"başa taxmaq; örtmək","en":"to wear on the head; to cover","ru":"надевать на голову; покрывать"},"n":{"az":"帽子をかぶる papaq taxmaq, かぶっています isə taxmış vəziyyətdə olmaq deməkdir.","en":"帽子をかぶる means to put on a hat, while かぶっています describes wearing it.","ru":"帽子をかぶる означает надеть шляпу, а かぶっています - быть в шляпе."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"きれい":{"b":"きれい","p":"an","m":{"az":"gözəl, təmiz","en":"beautiful, clean","ru":"красивый, чистый"},"n":{"az":"な-sifətdir: きれいな花 = gözəl çiçək; い ilə bitsə də い-sifət deyil.","en":"A na-adjective despite ending in い: きれいな花 = beautiful flower.","ru":"Это な-прилагательное, несмотря на окончание い: きれいな花 = красивый цветок."}},"ここ":{"b":"ここ","p":"pr","m":{"az":"bura; burada","en":"here; this place","ru":"здесь; это место"},"n":{"az":"Danışana yaxın yeri bildirir.","en":"Refers to a place near the speaker.","ru":"Указывает на место рядом с говорящим."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"この":{"b":"この","p":"dm","m":{"az":"bu","en":"this","ru":"этот"},"n":{"az":"この大学 = bu universitet.","en":"この大学 = this university.","ru":"この大学 = этот университет."}},"これ":{"b":"これ","p":"pr","m":{"az":"bu; bu şey","en":"this; this thing","ru":"это; эта вещь"},"n":{"az":"Danışana yaxın şeyi bildirir və isimdən əvvəl işlənmir; isimdən əvvəl この gəlir.","en":"Refers to something near the speaker; use この before a noun.","ru":"Указывает на предмет рядом с говорящим; перед существительным используется この."}},"ごめん":{"b":"ごめん","p":"n","m":{"az":"üzr; bağışlanma","en":"apology; forgiveness","ru":"извинение; прощение"},"n":{"az":"ごめん gündəlik danışıqda üzr istəmək üçün işlənir.","en":"ごめん is an informal way to apologize.","ru":"ごめん используется для неформального извинения."}},"さくら":{"b":"さくら","p":"nm","m":{"az":"Sakura (ad; 'albalı çiçəyi')","en":"Sakura (a name; 'cherry blossom')","ru":"Сакура (название; 'вишня')"}},"すむ":{"b":"済む (すむ)","p":"v","m":{"az":"bitmək; həll olunmaq","en":"to finish; to be settled","ru":"заканчиваться; улаживаться"},"n":{"az":"すみません sabit üzr ifadəsidir, bu kontekstdə bitmək mənasında deyil.","en":"すみません is a fixed apology expression, not the literal meaning of 済む.","ru":"すみません - устойчивое извинение, а не буквальное значение 済む."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"だ":{"b":"だ (だ)","p":"cp","m":{"az":"-dır, -dir; olmaq","en":"to be; is, am, are","ru":"быть; являться"},"n":{"az":"なら şərt formasıdır: 学生なら, əgər tələbədirsə.","en":"なら is a conditional form: 学生なら means if someone is a student.","ru":"なら является условной формой: 学生なら означает если он студент."}},"だけ":{"b":"だけ","p":"pt","m":{"az":"yalnız, ancaq","en":"only, just","ru":"только"},"n":{"az":"一度だけ = bircə dəfə; まんなかの星だけ = yalnız ortadakı ulduz.","en":"一度だけ = just once.","ru":"一度だけ = только один раз."}},"つける":{"b":"付ける (つける)","p":"v","m":{"az":"qoymaq (ad), taxmaq","en":"to give (a name), attach","ru":"давать (имя), прикреплять"},"n":{"az":"名前をつける = ad qoymaq.","en":"名前をつける = give a name.","ru":"名前をつける = дать имя."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"なさる":{"b":"なさる","p":"v","m":{"az":"etmək (hörmətli forma)","en":"to do (honorific)","ru":"делать (уважительная форма)"},"n":{"az":"する felinin hörmətli formasıdır; なさい əmr və göstərişlərdə işlənir.","en":"Honorific form of する; なさい is used for instructions and commands.","ru":"Уважительная форма する; なさい используется в указаниях и приказах."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"ひみつ":{"b":"秘密 (ひみつ)","p":"n","m":{"az":"sirr; gizli məlumat","en":"secret","ru":"секрет; тайна"},"n":{"az":"秘密の söz birləşməsi gizli mənasını verir.","en":"秘密の means secret or confidential before a noun.","ru":"秘密の перед существительным означает тайный или секретный."}},"ほか":{"b":"他 (ほか)","p":"n","m":{"az":"başqa; digəri","en":"other; elsewhere","ru":"другой; остальное"},"n":{"az":"ほかの人 başqa adam, ほかに isə əlavə olaraq deməkdir.","en":"ほかの人 means another person, and ほかに means additionally.","ru":"ほかの人 означает другой человек, а ほかに - кроме того."}},"ぼく":{"b":"僕 (ぼく)","p":"pr","m":{"az":"mən","en":"I","ru":"я"},"n":{"az":"Əsasən oğlanların və kişilərin işlətdiyi birinci şəxs əvəzliyidir.","en":"A first-person pronoun used mainly by boys and men.","ru":"Местоимение первого лица, употребляемое преимущественно мальчиками и мужчинами."}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"やがて":{"b":"やがて","p":"ad","m":{"az":"bir müddət sonra; nəhayət","en":"before long; eventually","ru":"вскоре; со временем"}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"りっぱ":{"b":"立派 (りっぱ)","p":"an","m":{"az":"möhtəşəm; əla; ləyaqətli","en":"splendid; admirable","ru":"великолепный; достойный"},"n":{"az":"な-sifətdir; isimdən əvvəl 立派な işlənir.","en":"It is a na-adjective; 立派な is used before a noun.","ru":"Это na-прилагательное; перед существительным используется 立派な."}},"わかる":{"b":"分かる (わかる)","p":"v","m":{"az":"başa düşmək; anlamaq","en":"understand","ru":"понимать"},"n":{"az":"Başa düşülən şey adətən が ilə göstərilir: 日本語が分かる.","en":"What is understood usually takes が: 日本語が分かる.","ru":"То, что понимают, обычно оформляется частицей が: 日本語が分かる."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"カタログ":{"b":"カタログ","p":"n","m":{"az":"kataloq","en":"catalogue","ru":"каталог"}},"シロ":{"b":"シロ (しろ)","p":"nm","m":{"az":"Şiro, it adı","en":"Shiro, a dog's name","ru":"Сиро, кличка собаки"}},"プレゼント":{"b":"プレゼント","p":"n","m":{"az":"hədiyyə","en":"present, gift","ru":"подарок"}},"ボタン":{"b":"ボタン","p":"n","m":{"az":"düymə","en":"button","ru":"кнопка; пуговица"},"n":{"az":"Həm cihaz düyməsi, həm də geyim düyməsi üçün işlənir.","en":"Used for both device buttons and clothing buttons.","ru":"Употребляется для кнопок устройств и пуговиц одежды."}},"ミナ":{"b":"ミナ","p":"nm","m":{"az":"Mina","en":"Mina","ru":"Мина"}},"レン":{"b":"レン","p":"nm","m":{"az":"Ren","en":"Ren","ru":"Рэн"}},"一つ":{"b":"一つ (ひとつ)","p":"n","m":{"az":"bir (dənə)","en":"one (thing)","ru":"одна (штука)"},"n":{"az":"Ümumi sayğac: 一つ, 二つ, 三つ.","en":"General counter: 一つ, 二つ, 三つ.","ru":"Общий счёт: 一つ, 二つ, 三つ."}},"一緒":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlik, bir yerdə olma","en":"being together","ru":"совместность, пребывание вместе"},"n":{"az":"一緒に “birlikdə” deməkdir: 友達と一緒に “dostla birlikdə”.","en":"一緒に means “together,” as in 友達と一緒に “together with a friend.”","ru":"一緒に означает «вместе»: 友達と一緒に «вместе с другом»."}},"丁寧":{"b":"丁寧 (ていねい)","p":"an","m":{"az":"nəzakətli; diqqətli; səliqəli","en":"polite; careful","ru":"вежливый; тщательный"},"n":{"az":"な-sifətdir; 丁寧に zərf kimi nəzakətlə və ya diqqətlə deməkdir.","en":"It is a na-adjective; 丁寧に means politely or carefully.","ru":"Это na-прилагательное; 丁寧に означает вежливо или тщательно."}},"三つ":{"b":"三つ (みっつ)","p":"n","m":{"az":"üç (dənə)","en":"three (things)","ru":"три (штуки)"}},"三人":{"b":"三人 (さんにん)","p":"nu","m":{"az":"üç nəfər","en":"three people","ru":"три человека"},"n":{"az":"人 insan sayğacıdır: 一人 hitori, 二人 futari, 三人 sannin.","en":"人 counts people: 一人 hitori, 二人 futari, 三人 sannin.","ru":"人 считает людей: 一人 hitori, 二人 futari, 三人 sannin."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"二つ":{"b":"二つ (ふたつ)","p":"n","m":{"az":"iki (dənə)","en":"two (things)","ru":"две (штуки)"}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"人形":{"b":"人形 (にんぎょう)","p":"n","m":{"az":"gəlincik; kukla","en":"doll; puppet","ru":"кукла"}},"今":{"b":"今 (いま)","p":"n","m":{"az":"indi","en":"now","ru":"сейчас"},"n":{"az":"今も = indi də.","en":"今も = even now.","ru":"今も = и сейчас."}},"仕事":{"b":"仕事 (しごと)","p":"n","m":{"az":"iş","en":"work, job","ru":"работа"}},"休む":{"b":"休む (やすむ)","p":"v","m":{"az":"istirahət etmək, işə və ya dərsə getməmək","en":"rest, take time off","ru":"отдыхать, пропускать работу или занятия"},"n":{"az":"学校を休む “dərsə getməmək”, 会社を休む isə “işə getməmək” deməkdir.","en":"学校を休む means “miss school,” and 会社を休む means “take time off work.”","ru":"学校を休む означает «пропускать занятия», а 会社を休む означает «не идти на работу»."}},"住む":{"b":"住む (すむ)","p":"v","m":{"az":"yaşamaq, məskunlaşmaq","en":"to live, to reside","ru":"жить, проживать"},"n":{"az":"住んで て-formadır, 場所に住む müəyyən yerdə yaşamaq deməkdir.","en":"住んで is the te-form, and 場所に住む means to live in a place.","ru":"住んで - форма на て, 場所に住む означает жить в определённом месте."}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"働く":{"b":"働く (はたらく)","p":"v","m":{"az":"işləmək","en":"to work","ru":"работать"},"n":{"az":"İş yerini で göstərir: 銀行で働きます.","en":"The workplace takes で: 銀行で働きます.","ru":"Место работы обозначается через で: 銀行で働きます."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"入れる":{"b":"入れる (いれる)","p":"v","m":{"az":"içəri qoymaq; daxil etmək","en":"to put in; to insert","ru":"класть внутрь; вставлять"},"n":{"az":"Təsirlidir: 箱に入れる; təsirsiz qarşılığı 入る-dur.","en":"Transitive: 箱に入れる; its intransitive partner is 入る.","ru":"Переходный: 箱に入れる; непереходная пара: 入る."}},"全部":{"b":"全部 (ぜんぶ)","p":"n","m":{"az":"hamısı, bütün","en":"all, everything","ru":"всё, целиком"},"n":{"az":"全部で = ümumilikdə; 全部食べました = hamısını yedim.","en":"全部で = in total; 全部食べました = ate everything.","ru":"全部で = всего; 全部食べました = съел всё."}},"写真":{"b":"写真 (しゃしん)","p":"n","m":{"az":"fotoşəkil","en":"photograph","ru":"фотография"}},"出かける":{"b":"出かける (でかける)","p":"v","m":{"az":"evdən çıxmaq; yola düşmək","en":"go out; set off","ru":"выходить; отправляться"}},"初めて":{"b":"初めて (はじめて)","p":"ad","m":{"az":"ilk dəfə","en":"for the first time","ru":"впервые"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"割れる":{"b":"割れる (われる)","p":"v","m":{"az":"sınmaq; çatlamaq","en":"to break; to crack","ru":"разбиваться; трескаться"},"n":{"az":"自動詞: 割れる sınmaq, 割る isə sındırmaq deməkdir.","en":"Intransitive verb: 割れる means to break, while 割る means to break something.","ru":"Непереходный глагол: 割れる - разбиваться, 割る - разбивать."}},"医者":{"b":"医者 (いしゃ)","p":"n","m":{"az":"həkim","en":"doctor","ru":"врач"}},"十":{"b":"十 (じゅう)","p":"nu","m":{"az":"on","en":"ten","ru":"десять"}},"十人":{"b":"十人 (じゅうにん)","p":"nu","m":{"az":"on nəfər","en":"ten people","ru":"десять человек"},"n":{"az":"人 insanları sayır, 十人 じゅうにん oxunur.","en":"人 counts people, and 十人 is pronounced じゅうにん.","ru":"Счётный суффикс 人 для людей, 十人 читается じゅうにん."}},"卵":{"b":"卵 (たまご)","p":"n","m":{"az":"yumurta","en":"egg","ru":"яйцо"}},"友達":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг"}},"取る":{"b":"取る (とる)","p":"v","m":{"az":"götürmək, almaq","en":"to take, to pick up","ru":"брать, поднимать"},"n":{"az":"Əşyanı götürmək üçün 取る, şəkil çəkmək üçün eyni oxunuşlu 撮る işlənir.","en":"Use 取る for taking an object and the identically pronounced 撮る for taking a photo.","ru":"Для взятия предмета используется 取る, а для фотографии используется 撮る с тем же чтением."}},"古い":{"b":"古い (ふるい)","p":"ai","m":{"az":"köhnə; qədim","en":"old","ru":"старый; древний"},"n":{"az":"İ-sifətdir; əşya və tikililər üçün işlənir, insanın yaşını bildirmir.","en":"An i-adjective used for things and buildings, not a person's age.","ru":"И-прилагательное для вещей и зданий, не для возраста человека."}},"台所":{"b":"台所 (だいどころ)","p":"n","m":{"az":"mətbəx","en":"kitchen","ru":"кухня"}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"向かう":{"b":"向かう (むかう)","p":"v","m":{"az":"istiqamətlənmək; tərəfə getmək","en":"to head toward; to face","ru":"направляться; быть обращённым"},"n":{"az":"場所に向かう bir yerə doğru getmək deməkdir.","en":"場所に向かう means to head toward a place.","ru":"場所に向かう означает направляться к месту."}},"向こう":{"b":"向こう (むこう)","p":"n","m":{"az":"o tərəf, qarşı tərəf","en":"over there, the other side","ru":"там, противоположная сторона"}},"壁":{"b":"壁 (かべ)","p":"n","m":{"az":"divar","en":"wall","ru":"стена"}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"売る":{"b":"売る (うる)","p":"v","m":{"az":"satmaq","en":"sell","ru":"продавать"}},"外":{"b":"外 (そと)","p":"n","m":{"az":"çöl, bayır","en":"outside","ru":"снаружи"},"n":{"az":"N の 外 = N-in çölü: 窓の外 = pəncərənin arxası (çöldə).","en":"N の 外 = outside N.","ru":"N の 外 = снаружи N."}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"奥":{"b":"奥 (おく)","p":"n","m":{"az":"içəri tərəf; dərinlik","en":"inner part; back","ru":"глубина; дальняя часть"},"n":{"az":"Yerə görə otağın içəri tərəfini, mağazanın arxasını və ya meşənin dərinliyini bildirir.","en":"Depending on the place, it means the inner part of a room, the back of a shop, or deep inside a forest.","ru":"В зависимости от места обозначает глубину комнаты, дальнюю часть магазина или глубь леса."}},"女":{"b":"女 (おんな)","p":"n","m":{"az":"qadın","en":"woman; female","ru":"женщина"},"n":{"az":"Nəzakətli gündəlik danışıqda qadın üçün 女の人 daha uyğundur.","en":"女の人 is usually more polite when referring to a woman in everyday speech.","ru":"В повседневной вежливой речи о женщине обычно говорят 女の人."}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"子たち":{"b":"子たち (こたち)","p":"n","m":{"az":"balalar; uşaqlar","en":"children; young ones","ru":"дети; детёныши"},"n":{"az":"子 insan uşağı və ya heyvan balası ola bilər; たち cəmlik bildirir.","en":"子 can mean a child or animal offspring; たち marks plurality.","ru":"子 может означать ребёнка или детёныша; たち обозначает множественное число."}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"学生":{"b":"学生 (がくせい)","p":"n","m":{"az":"tələbə","en":"student","ru":"студент"}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"家族":{"b":"家族 (かぞく)","p":"n","m":{"az":"ailə","en":"family","ru":"семья"}},"寒い":{"b":"寒い (さむい)","p":"ai","m":{"az":"soyuq","en":"cold, chilly","ru":"холодный, прохладный"},"n":{"az":"い-sifətdir; əsasən hava üçün işlənir, toxunanda soyuq əşyalar üçün 冷たい deyilir.","en":"An i-adjective mainly for cold weather; use 冷たい for cold objects.","ru":"Прилагательное на い, обычно о погоде; для холодных предметов используют 冷たい."}},"寮":{"b":"寮 (りょう)","p":"n","m":{"az":"yataqxana","en":"dormitory","ru":"общежитие"}},"小さい":{"b":"小さい (ちいさい)","p":"ai","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"i-sifət; isimdən əvvəl olduğu kimi gəlir: 小さい子 = balaca uşaq.","en":"i-adjective; goes straight before a noun: 小さい子 = a little child.","ru":"i-прилагательное; ставится прямо перед существительным."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"履く":{"b":"履く (はく)","p":"v","m":{"az":"ayağa geyinmək","en":"to put on footwear or lower-body clothing","ru":"надевать обувь или одежду на нижнюю часть тела"},"n":{"az":"Ayaqqabı, corab, şalvar üçün işlənir; 履いていました keçmişdə geyinmiş vəziyyəti bildirir.","en":"Used for shoes, socks and trousers; 履いていました describes a past state of wearing them.","ru":"Используется для обуви, носков и брюк; 履いていました описывает состояние в прошлом."}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"市":{"b":"市 (し)","p":"n","m":{"az":"şəhər; bələdiyyə ərazisi","en":"city; municipality","ru":"город; муниципалитет"},"n":{"az":"Şəhər inzibati vahidi kimi し oxunur.","en":"Read し when referring to a city as an administrative unit.","ru":"Читается し, когда обозначает город как административную единицу."}},"布":{"b":"布 (ぬの)","p":"n","m":{"az":"parça","en":"cloth, fabric","ru":"ткань"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"帽子":{"b":"帽子 (ぼうし)","p":"n","m":{"az":"papaq; şlyapa","en":"hat; cap","ru":"шляпа; шапка"}},"床":{"b":"床 (ゆか)","p":"n","m":{"az":"döşəmə","en":"floor","ru":"пол"}},"店":{"b":"店 (みせ)","p":"n","m":{"az":"mağaza; dükan","en":"shop; store","ru":"магазин; лавка"}},"座る":{"b":"座る (すわる)","p":"v","m":{"az":"oturmaq","en":"sit down","ru":"садиться"},"n":{"az":"Oturulan yer に ilə göstərilir: 椅子に座る “stulda oturmaq”.","en":"The seat or sitting place takes に: 椅子に座る “sit on a chair.”","ru":"Место обозначается с に: 椅子に座る «сесть на стул»."}},"庭":{"b":"庭 (にわ)","p":"n","m":{"az":"bağça, həyət","en":"garden, yard","ru":"сад, двор"}},"廊下":{"b":"廊下 (ろうか)","p":"n","m":{"az":"dəhliz","en":"corridor, hallway","ru":"коридор"}},"役所":{"b":"役所 (やくしょ)","p":"n","m":{"az":"dövlət idarəsi; bələdiyyə idarəsi","en":"government office; municipal office","ru":"государственное учреждение; муниципалитет"},"n":{"az":"市役所 şəhər bələdiyyəsi idarəsi deməkdir.","en":"市役所 means city hall or municipal office.","ru":"市役所 означает городскую администрацию."}},"忘れる":{"b":"忘れる (わすれる)","p":"v","m":{"az":"unutmaq","en":"to forget","ru":"забывать"},"n":{"az":"Nを忘れる həm nəyisə unutmaq, həm də bir yerdə qoyub gəlmək mənasında işlənir.","en":"Nを忘れる can mean to forget something or leave it behind.","ru":"Nを忘れる может означать забыть что-либо или оставить это где-либо."}},"思い出す":{"b":"思い出す (おもいだす)","p":"v","m":{"az":"xatırlamaq, yada salmaq","en":"remember, recall","ru":"вспоминать"}},"急ぐ":{"b":"急ぐ (いそぐ)","p":"v","m":{"az":"tələsmək","en":"hurry","ru":"спешить"},"n":{"az":"て forması 急いで olur.","en":"Its て-form is 急いで.","ru":"Форма на て: 急いで."}},"悲しい":{"b":"悲しい (かなしい)","p":"ai","m":{"az":"kədərli","en":"sad","ru":"грустный"},"n":{"az":"İ-sifətidir; 悲しく zərf formasıdır və “kədərli şəkildə” mənasını verir.","en":"An i-adjective; 悲しく is its adverbial form, meaning “sadly.”","ru":"Прилагательное на い; 悲しく является наречной формой со значением «грустно»."}},"戸":{"b":"戸 (と)","p":"n","m":{"az":"qapı","en":"door","ru":"дверь"}},"手":{"b":"手 (て)","p":"n","m":{"az":"əl","en":"hand","ru":"рука"}},"抱く":{"b":"抱く (だく)","p":"v","m":{"az":"qucaqlamaq; qucaqda tutmaq","en":"to hug; to hold in one's arms","ru":"обнимать; держать на руках"},"n":{"az":"抱く qucaqlamaq mənasında だく, hiss bəsləmək mənasında isə çox vaxt いだく oxunur.","en":"抱く is read だく for holding someone and often いだく for harboring feelings.","ru":"抱く читается だく при объятии и часто いだく при обозначении чувств."}},"挟まる":{"b":"挟まる (はさまる)","p":"v","m":{"az":"arasında qalmaq; ilişmək","en":"to get caught between; to be stuck","ru":"застревать; быть зажатым"},"n":{"az":"自動詞: 挟まる ilişmək, 挟む isə arasına qoymaq və ya sıxmaq deməkdir.","en":"Intransitive verb: 挟まる means to get stuck, while 挟む means to sandwich or夹 something.","ru":"Непереходный глагол: 挟まる - застревать, 挟む - зажимать."}},"振る":{"b":"振る (ふる)","p":"v","m":{"az":"yelləmək; silkələmək","en":"wave; shake","ru":"махать; трясти"},"n":{"az":"手を振る əl yelləmək, 首を振る isə başı yelləmək deməkdir.","en":"手を振る means to wave a hand; 首を振る means to shake one's head.","ru":"手を振る означает махать рукой, а 首を振る качать головой."}},"捜す":{"b":"捜す (さがす)","p":"v","m":{"az":"axtarmaq","en":"search for","ru":"разыскивать"},"n":{"az":"捜す əsasən itmiş şəxs və ya əşyanı axtarmaq üçün, 探す isə daha ümumi axtarış üçün işlənir.","en":"捜す is mainly used for searching for a missing person or thing, while 探す is more general.","ru":"捜す обычно означает поиск пропавшего человека или вещи, а 探す имеет более общее значение."}},"教える":{"b":"教える (おしえる)","p":"v","m":{"az":"öyrətmək; demək (məlumat vermək)","en":"to teach; to tell","ru":"учить; сообщать"},"n":{"az":"名前を教えてください = adınızı deyin (zəhmət olmasa).","en":"名前を教えてください = please tell me your name.","ru":"名前を教えてください = скажите, пожалуйста, имя."}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"春":{"b":"春 (はる)","p":"n","m":{"az":"yaz (fəsil)","en":"spring","ru":"весна"}},"昨日":{"b":"昨日 (きのう)","p":"n","m":{"az":"dünən","en":"yesterday","ru":"вчера"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 昨日来ました.","en":"Usually takes no に as a time expression: 昨日来ました.","ru":"При обозначении времени обычно употребляется без に: 昨日来ました."}},"時":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, zaman","en":"time, occasion","ru":"время, момент"},"n":{"az":"時 “vaxt” mənasında とき, saat bildirən rəqəmdən sonra isə じ oxunur: 三時 “saat üç”.","en":"時 is read とき for “time” but じ after a number indicating the hour: 三時 “three o'clock.”","ru":"時 читается とき в значении «время», но じ после числа, обозначающего час: 三時 «три часа»."}},"晩":{"b":"晩 (ばん)","p":"n","m":{"az":"axşam","en":"evening","ru":"вечер"}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"服":{"b":"服 (ふく)","p":"n","m":{"az":"paltar","en":"clothes","ru":"одежда"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"机":{"b":"机 (つくえ)","p":"n","m":{"az":"yazı masası","en":"desk","ru":"письменный стол"}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"棚":{"b":"棚 (たな)","p":"n","m":{"az":"rəf","en":"shelf","ru":"полка"}},"横":{"b":"横 (よこ)","p":"n","m":{"az":"yan; böyür","en":"side; beside","ru":"бок; рядом"},"n":{"az":"Nの横 = N-in yanı; üfüqi istiqamət mənası da var.","en":"Nの横 means beside N; 横 can also refer to a horizontal direction.","ru":"Nの横 означает рядом с N; 横 также обозначает горизонтальное направление."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"歯":{"b":"歯 (は)","p":"n","m":{"az":"diş","en":"tooth","ru":"зуб"}},"残す":{"b":"残す (のこす)","p":"v","m":{"az":"saxlamaq; artıq qoymaq","en":"to leave behind; to keep","ru":"оставлять; сохранять"},"n":{"az":"他動詞: 残す saxlamaq, 残る isə qalmaq deməkdir; 残してください xahiş formasıdır.","en":"Transitive verb: 残す means to leave something, 残る means to remain, and 残してください is a polite request.","ru":"Переходный глагол: 残す - оставлять, 残る - оставаться, а 残してください - вежливая просьба."}},"母":{"b":"母 (はは)","p":"n","m":{"az":"ana","en":"mother","ru":"мать"},"n":{"az":"Başqaları ilə danışarkən öz ananı bildirmək üçün işlənir; anaya müraciətdə adətən お母さん deyilir.","en":"Used for one's own mother when speaking to others; お母さん is usual when addressing her.","ru":"Употребляется о своей матери в разговоре с другими; при обращении к ней обычно используется お母さん."}},"毎年":{"b":"毎年 (まいとし／まいねん)","p":"ad","m":{"az":"hər il","en":"every year","ru":"каждый год"}},"毎晩":{"b":"毎晩 (まいばん)","p":"n","m":{"az":"hər axşam; hər gecə","en":"every evening; every night","ru":"каждый вечер; каждую ночь"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎晩読みます.","en":"Takes no に as a time expression: 毎晩読みます.","ru":"При обозначении времени употребляется без に: 毎晩読みます."}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"消える":{"b":"消える (きえる)","p":"v","m":{"az":"sönmək, yox olmaq","en":"to go out, disappear","ru":"гаснуть, исчезать"},"n":{"az":"消えそうになる = az qala sönmək.","en":"消えそうになる = be about to go out.","ru":"消えそうになる = вот-вот погаснуть."}},"渡す":{"b":"渡す (わたす)","p":"v","m":{"az":"vermək, uzatmaq","en":"hand over, pass","ru":"передавать"},"n":{"az":"Keçişli feldir: 人に物を渡す “kiməsə nəsə vermək”; 渡る isə “qarşı tərəfə keçmək” deməkdir.","en":"A transitive verb: 人に物を渡す means “hand something to someone”; 渡る means “cross.”","ru":"Переходный глагол: 人に物を渡す «передать кому-то что-то»; 渡る означает «пересекать, переходить»."}},"温かい":{"b":"温かい (あたたかい)","p":"ai","m":{"az":"isti; ilıq; mehriban","en":"warm; kind","ru":"тёплый; душевный"},"n":{"az":"い-sifətidir; əşya və münasibətlər üçün 温かい, hava üçün adətən 暖かい yazılır.","en":"An い-adjective; 温かい is used for objects and kindness, while weather usually takes 暖かい.","ru":"い-прилагательное; 温かい относится к предметам и душевной теплоте, а для погоды обычно пишут 暖かい."}},"父":{"b":"父 (ちち)","p":"n","m":{"az":"ata","en":"father","ru":"отец"},"n":{"az":"Öz atanızdan danışarkən 父, başqasının atasına müraciətdə お父さん işlənir.","en":"Use 父 for your own father and お父さん when addressing or referring politely to someone else's father.","ru":"父 используется для своего отца, а お父さん - при вежливом обращении или упоминании чужого отца."}},"玄関":{"b":"玄関 (げんかん)","p":"n","m":{"az":"evin giriş hissəsi, dəhliz","en":"entrance hall, entryway","ru":"прихожая, входная зона"},"n":{"az":"Yapon evlərində ayaqqabının çıxarıldığı giriş yeridir.","en":"The entrance area of a Japanese home where shoes are removed.","ru":"Входная зона японского дома, где снимают обувь."}},"甘い":{"b":"甘い (あまい)","p":"ai","m":{"az":"şirin, yumşaq","en":"sweet, lenient","ru":"сладкий, снисходительный"},"n":{"az":"い-sifətdir: 甘くない = şirin deyil; davranış haqqında yumşaqlıq da bildirir.","en":"An i-adjective: 甘くない = not sweet; it can also mean lenient.","ru":"Прилагательное на い: 甘くない = несладкий; также может означать снисходительный."}},"白い":{"b":"白い (しろい)","p":"ai","m":{"az":"ağ","en":"white","ru":"белый"}},"皆さん":{"b":"皆さん (みなさん)","p":"n","m":{"az":"hamınız; hər kəs","en":"everyone; all of you","ru":"все; вы все"},"n":{"az":"Bir qrupa nəzakətli müraciət üçün işlənir.","en":"Used to address a group politely.","ru":"Используется для вежливого обращения к группе."}},"着る":{"b":"着る (きる)","p":"v","m":{"az":"geyinmək (paltar)","en":"to wear, put on","ru":"надевать"},"n":{"az":"白い服を着たねこ = ağ paltar geyinmiş pişik (feil təyin kimi).","en":"白い服を着たねこ = a cat wearing white.","ru":"白い服を着たねこ = кошка в белом."}},"知る":{"b":"知る (しる)","p":"v","m":{"az":"bilmək, tanımaq","en":"to know","ru":"знать"},"n":{"az":"Bilmirəm demək üçün 知りません deyilir. 知りませんでした = bilmirdilər (nəzakətli inkar, keçmiş).","en":"Negative: 知りません. 知りませんでした = did not know.","ru":"Отрицание: 知りません. 知りませんでした = не знали."}},"祖父":{"b":"祖父 (そふ)","p":"n","m":{"az":"baba","en":"grandfather","ru":"дедушка"},"n":{"az":"Öz babasından danışarkən 祖父, müraciətdə və başqasının babası üçün adətən おじいさん işlənir.","en":"Use 祖父 for your own grandfather; おじいさん is usual for addressing him or referring to someone else's.","ru":"祖父 используется для своего дедушки; при обращении или для чужого дедушки обычно употребляют おじいさん."}},"私":{"b":"私 (わたし)","p":"pr","m":{"az":"mən","en":"I; me","ru":"я; меня"},"n":{"az":"Nəzakətli, neytral birinci şəxs əvəzliyidir və kontekstdən aydın olduqda buraxılır.","en":"A polite, neutral first-person pronoun, often omitted when clear from context.","ru":"Вежливое нейтральное местоимение первого лица, часто опускаемое, если понятно из контекста."}},"窓":{"b":"窓 (まど)","p":"n","m":{"az":"pəncərə","en":"window","ru":"окно"}},"立つ":{"b":"立つ (たつ)","p":"v","m":{"az":"dayanmaq, ayağa qalxmaq","en":"to stand","ru":"стоять, вставать"}},"竹":{"b":"竹 (たけ)","p":"n","m":{"az":"bambuk","en":"bamboo","ru":"бамбук"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"箱":{"b":"箱 (はこ)","p":"n","m":{"az":"qutu","en":"box","ru":"коробка"}},"約束":{"b":"約束 (やくそく)","p":"n","m":{"az":"söz; görüş razılaşması","en":"promise; appointment","ru":"обещание; договорённость о встрече"},"n":{"az":"約束する = söz vermək və ya görüş barədə razılaşmaq.","en":"約束する means to promise or arrange to meet.","ru":"約束する означает обещать или договариваться о встрече."}},"置く":{"b":"置く (おく)","p":"v","m":{"az":"qoymaq","en":"to put, place","ru":"класть, ставить"}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"花":{"b":"花 (はな)","p":"n","m":{"az":"çiçək","en":"flower","ru":"цветок"}},"若い":{"b":"若い (わかい)","p":"ai","m":{"az":"gənc, cavan","en":"young","ru":"молодой"},"n":{"az":"İ-sifətidir: 若い人 “gənc insan”.","en":"An i-adjective: 若い人 means “a young person.”","ru":"Прилагательное на い: 若い人 «молодой человек»."}},"落ちる":{"b":"落ちる (おちる)","p":"v","m":{"az":"düşmək, yıxılmaq","en":"to fall","ru":"падать"},"n":{"az":"落ちて来る = düşüb gəlmək (aşağı).","en":"落ちて来る = come falling down.","ru":"落ちて来る = упасть (сюда)."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"触る":{"b":"触る (さわる)","p":"v","m":{"az":"toxunmaq","en":"to touch","ru":"трогать; прикасаться"},"n":{"az":"Adətən N に触る şəklində işlənir: ボタンに触る.","en":"Usually takes に: ボタンに触る means to touch a button.","ru":"Обычно используется с に: ボタンに触る означает касаться кнопки."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"話す":{"b":"話す (はなす)","p":"v","m":{"az":"danışmaq; söhbət etmək","en":"to speak; to talk","ru":"говорить; разговаривать"},"n":{"az":"Dil を, həmsöhbət と ilə göstərilir: 日本語を話す, 友達と話す.","en":"A language takes を and a conversation partner takes と: 日本語を話す, 友達と話す.","ru":"Язык обозначается через を, собеседник через と: 日本語を話す, 友達と話す."}},"話せる":{"b":"話せる (はなせる)","p":"v","m":{"az":"danışa bilmək","en":"to be able to speak","ru":"уметь говорить"},"n":{"az":"話す felinin potensial formasıdır; 話せませんでした keçmişdə danışa bilmədi deməkdir.","en":"Potential form of 話す; 話せませんでした means could not speak.","ru":"Потенциальная форма 話す; 話せませんでした означает не мог говорить."}},"誕生":{"b":"誕生 (たんじょう)","p":"n","m":{"az":"doğulma, yaranma","en":"birth, creation","ru":"рождение, возникновение"},"n":{"az":"“Ad günü” üçün 誕生日 işlənir; 誕生する “doğulmaq, yaranmaq” deməkdir.","en":"“Birthday” is 誕生日; 誕生する means “be born” or “come into being.”","ru":"«День рождения» обозначается словом 誕生日; 誕生する означает «родиться, возникнуть»."}},"謝る":{"b":"謝る (あやまる)","p":"v","m":{"az":"üzr istəmək","en":"to apologize","ru":"извиняться"},"n":{"az":"人に謝る kimdənsə üzr istəmək deməkdir.","en":"人に謝る means to apologize to someone.","ru":"人に謝る означает извиняться перед кем-либо."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"赤ちゃん":{"b":"赤ちゃん (あかちゃん)","p":"n","m":{"az":"körpə","en":"baby; infant","ru":"младенец; малыш"}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"通れる":{"b":"通れる (とおれる)","p":"v","m":{"az":"keçə bilmək","en":"to be able to pass through","ru":"мочь пройти"},"n":{"az":"通る felinin potensial formasıdır; 通れます keçmək mümkündür deməkdir.","en":"Potential form of 通る; 通れます means can pass through.","ru":"Потенциальная форма 通る; 通れます означает можно пройти."}},"遊ぶ":{"b":"遊ぶ (あそぶ)","p":"v","m":{"az":"oynamaq; əylənmək","en":"to play; to have fun","ru":"играть; развлекаться"},"n":{"az":"て-forması 遊んで-dir; 友達と遊ぶ = dostlarla oynamaq və ya vaxt keçirmək.","en":"Its て-form is 遊んで; 友達と遊ぶ means to play or spend time with friends.","ru":"て-форма: 遊んで; 友達と遊ぶ означает играть или проводить время с друзьями."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"里":{"b":"里 (さと)","p":"n","m":{"az":"doğma kənd; kənd yeri","en":"home village; rural village","ru":"родная деревня; сельская местность"}},"針":{"b":"針 (はり)","p":"n","m":{"az":"iynə; saat əqrəbi","en":"needle; clock hand","ru":"игла; стрелка часов"},"n":{"az":"Tikişdə iynə, 時計の針 ifadəsində isə saat əqrəbi deməkdir.","en":"It means a sewing needle, but a clock hand in 時計の針.","ru":"В шитье означает иглу, а в 時計の針 означает стрелку часов."}},"門":{"b":"門 (もん)","p":"n","m":{"az":"darvaza","en":"gate","ru":"ворота"}},"閉める":{"b":"閉める (しめる)","p":"v","m":{"az":"bağlamaq (qapı, pəncərə)","en":"to close; to shut","ru":"закрывать"},"n":{"az":"他動詞: 閉める bağlamaq, 閉まる isə bağlanmaq deməkdir.","en":"Transitive verb: 閉める means to close something, while 閉まる means to close by itself.","ru":"Переходный глагол: 閉める - закрывать, 閉まる - закрываться."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"隣":{"b":"隣 (となり)","p":"n","m":{"az":"yan, qonşuluq","en":"next door, next to","ru":"соседство, рядом"},"n":{"az":"Nの隣 birbaşa N-in yanındakı yeri bildirir.","en":"Nの隣 refers to a place directly next to N.","ru":"Nの隣 обозначает место непосредственно рядом с N."}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"靴":{"b":"靴 (くつ)","p":"n","m":{"az":"ayaqqabı","en":"shoes","ru":"обувь, туфли"}},"音":{"b":"音 (おと)","p":"n","m":{"az":"səs (əşya səsi)","en":"sound","ru":"звук"},"n":{"az":"音がする = səs gəlmək. İnsan səsi üçün 声.","en":"音がする = a sound is heard. Human voice: 声.","ru":"音がする = слышен звук. Голос человека – 声."}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"飲む":{"b":"飲む (のむ)","p":"v","m":{"az":"içmək","en":"drink","ru":"пить"},"n":{"az":"Dərman qəbul etmək üçün də işlənir: 薬を飲む.","en":"Also used for taking medicine: 薬を飲む.","ru":"Также употребляется для приёма лекарства: 薬を飲む."}},"首":{"b":"首 (くび)","p":"n","m":{"az":"boyun; baş","en":"neck; head","ru":"шея; голова"},"n":{"az":"首をふる = başını bulamaq (inkar).","en":"首をふる = shake one's head.","ru":"首をふる = покачать головой."}},"駅":{"b":"駅 (えき)","p":"n","m":{"az":"stansiya","en":"station","ru":"станция"}},"鳥":{"b":"鳥 (とり)","p":"n","m":{"az":"quş","en":"bird","ru":"птица"}},"鳴く":{"b":"鳴く (なく)","p":"v","m":{"az":"heyvan səsi çıxarmaq; ötmək","en":"make an animal sound; chirp","ru":"издавать голос; петь о птицах"},"n":{"az":"Heyvan və quş səsləri üçün işlənir; insanın ağlaması eyni oxunuşlu 泣く ilə yazılır.","en":"Used for animal and bird cries; human crying is written 泣く with the same reading.","ru":"Употребляется для голосов животных и птиц; человеческий плач записывается 泣く с тем же чтением."}}}};